'use strict';
const byId=id=>document.getElementById(id);
const facts=[
 {title:'同步自转',section:'§ 01 / 中文整理节选',text:'月球自转与绕地公转同步，大致以同一半球朝向地球。该小节将两种运动时间概括为约 27 个地球日。',limit:'保留“约”的限定，不将资料中的概括值改成未经提供的精确参数。',source:0},
 {title:'背面不是永久黑暗',section:'§ 02 / 中文整理节选',text:'月球背面并非永久黑暗，月球不同区域会在不同时刻受到太阳照射。',limit:'“背面”与“没有光照”不能互换。此依据只来自当前示例材料。',source:1},
 {title:'所提供公开资料不足',section:'§ 03 / 材料范围说明',text:'本整理节选不包含具体任务的燃料消耗或发动机参数。',limit:'只能说明这份材料未提供，不能据此宣称全部公开资料都没有。',source:2}
];
let toastTimer,selectedVersion='popular',savedText='';
function toast(message){byId('toast').textContent=message;byId('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>byId('toast').classList.add('hidden'),4500);}
function showPage(page){document.querySelectorAll('.page').forEach(el=>el.classList.toggle('hidden',el.id!==page));document.querySelectorAll('[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===page));window.scrollTo({top:0,behavior:'instant'});}
document.querySelectorAll('[data-page]').forEach(el=>el.addEventListener('click',()=>showPage(el.dataset.page)));
byId('brand').addEventListener('click',event=>{event.preventDefault();showPage('studio');});
function selectFact(index){const fact=facts[index];document.querySelectorAll('.fact-item').forEach(el=>{const active=Number(el.dataset.fact)===index;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});document.querySelectorAll('.source-paragraph').forEach((el,i)=>el.classList.toggle('highlight',i===fact.source));const panel=byId('evidence-detail');panel.replaceChildren();const label=document.createElement('span');label.className='micro';label.textContent='当前依据 / '+String(index+1).padStart(2,'0');const heading=document.createElement('h3');heading.textContent=fact.title;const position=document.createElement('p');position.className='anchor-text';position.textContent=fact.section;const quote=document.createElement('blockquote');quote.textContent=fact.text;const link=document.createElement('a');link.href='https://science.nasa.gov/moon/facts/';link.target='_blank';link.rel='noopener noreferrer';link.textContent=index===2?'查看示例材料来源 ↗':'核对 NASA 官方页面 ↗';const note=document.createElement('p');note.className='boundary-note';note.textContent=fact.limit;panel.append(label,heading,position,quote,link,note);}
document.querySelectorAll('[data-fact]').forEach(el=>el.addEventListener('click',()=>{selectFact(Number(el.dataset.fact));if(window.innerWidth<1250){toast('已更新下方“事实与依据”面板。');}}));
function setVersion(version){selectedVersion=version;byId('popular-output').classList.toggle('hidden',version!=='popular');byId('professional-output').classList.toggle('hidden',version!=='professional');byId('popular-tab').classList.toggle('active',version==='popular');byId('professional-tab').classList.toggle('active',version==='professional');byId('popular-tab').setAttribute('aria-pressed',String(version==='popular'));byId('professional-tab').setAttribute('aria-pressed',String(version==='professional'));byId('version-label').textContent=version==='popular'?'ADAPTED READING / 科普适配':'PROFESSIONAL SUMMARY / 专业摘要';}
byId('popular-tab').addEventListener('click',()=>setVersion('popular'));byId('professional-tab').addEventListener('click',()=>setVersion('professional'));
function setSource(mode){byId('sample-source').classList.toggle('hidden',mode!=='sample');byId('paste-source').classList.toggle('hidden',mode!=='paste');byId('sample-tab').classList.toggle('active',mode==='sample');byId('paste-tab').classList.toggle('active',mode==='paste');}
byId('sample-tab').addEventListener('click',()=>setSource('sample'));byId('paste-tab').addEventListener('click',()=>setSource('paste'));
byId('keep-source').addEventListener('click',()=>{const text=byId('user-source').value.trim();if(!text){byId('input-state').textContent='请先粘贴资料文本。';byId('user-source').focus();return;}savedText=text;byId('input-state').textContent='已保留 '+text.length+' 个字符。两版输出仍是固定示例，与此输入无关。';});
byId('demo-run').addEventListener('click',()=>{setSource('sample');setVersion('popular');selectFact(0);toast(savedText||byId('user-source').value.trim()?'已打开固定示例；尚未对你粘贴的资料进行分析。':'已打开预先编写的适配示例，未执行真实 AI 生成。');});
byId('reset').addEventListener('click',()=>{savedText='';byId('user-source').value='';byId('input-state').textContent='';setSource('sample');setVersion('popular');selectFact(0);toast('已恢复示例，临时输入已清除。');});
byId('export').addEventListener('click',()=>{const article=byId(selectedVersion==='popular'?'popular-output':'professional-output');const text='航天科普适配 · 预写演示内容\n未经过实时 AI 生成或自动核验\n\n'+article.innerText+'\n\n来源：NASA Moon Facts / Orbit and Rotation\nhttps://science.nasa.gov/moon/facts/\n本原型的源材料是中文整理节选，非官方中文原文。';const blob=new Blob([text],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=selectedVersion==='popular'?'高中生科普版-演示.txt':'专业摘要-演示.txt';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('已导出演示文本与来源说明。');});
byId('glossary-open').addEventListener('click',()=>byId('glossary').showModal());byId('glossary-close').addEventListener('click',()=>byId('glossary').close());
function toggleTweaks(open){byId('tweaks').classList.toggle('hidden',!open);byId('tweaks-toggle').setAttribute('aria-expanded',String(open));}
byId('tweaks-toggle').addEventListener('click',()=>toggleTweaks(byId('tweaks').classList.contains('hidden')));byId('tweaks-close').addEventListener('click',()=>toggleTweaks(false));byId('layout').addEventListener('change',event=>{document.body.classList.remove('reading','compare');if(event.target.value!=='standard')document.body.classList.add(event.target.value);});byId('text-size').addEventListener('change',event=>document.body.classList.toggle('large-text',event.target.value==='large'));
selectFact(0);
